<?php
declare(strict_types=1);require dirname(__DIR__).'/src/Api.php';require dirname(__DIR__).'/src/Auth.php';$c=require dirname(__DIR__).'/config/config.php';$origin=$_SERVER['HTTP_ORIGIN']??'';if($origin&&hash_equals($c['allowed_origin'],$origin)){header("Access-Control-Allow-Origin: $origin");header('Vary: Origin');}header('Access-Control-Allow-Headers: Authorization, Content-Type');header('Access-Control-Allow-Methods: GET, POST, OPTIONS');header("Content-Security-Policy: default-src 'none'; frame-ancestors 'none'");header('X-Content-Type-Options: nosniff');if(($_SERVER['REQUEST_METHOD']??'GET')==='OPTIONS'){http_response_code(204);exit;}$db=new PDO($c['dsn'],$c['user'],$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$user=(new Auth($db))->user(true);$method=$_SERVER['REQUEST_METHOD'];$action=$_GET['action']??'stats';
try{if($method==='GET'&&$action==='stats'){$q=$db->query("SELECT c.id,c.title,COUNT(s.id) submissions,SUM(s.is_correct) solves,COUNT(DISTINCT s.user_id) players FROM ctf_challenges c LEFT JOIN ctf_submissions s ON s.challenge_id=c.id GROUP BY c.id,c.title ORDER BY submissions DESC");Api::json($q->fetchAll());}if($method==='GET'&&$action==='export'){$rows=$db->query('SELECT public_id,category_id,title,slug,difficulty,scenario,learning_objective,solution,references_json,base_points,max_attempts,time_limit_minutes,is_active FROM ctf_challenges')->fetchAll();Api::json($rows);}if($method==='POST'&&$action==='challenge'){$b=Api::body();foreach(['category_id','title','slug','difficulty','scenario','learning_objective','flag','solution','base_points'] as $f)if(!isset($b[$f])||$b[$f]==='')Api::error("Kolom $f wajib",422);if(!in_array($b['difficulty'],['easy','medium','hard','expert'],true)||!preg_match('/^PEGASUS\{[A-Za-z0-9_:-]{3,140}\}$/',$b['flag']))Api::error('Level atau flag tidak valid',422);if(count($b['hints']??[])>3)Api::error('Maksimal tiga hint',422);$db->beginTransaction();$q=$db->prepare('INSERT INTO ctf_challenges(public_id,category_id,title,slug,difficulty,scenario,learning_objective,flag_hash,solution,references_json,base_points) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$q->execute(['PG-'.strtoupper(bin2hex(random_bytes(3))),$b['category_id'],strip_tags($b['title']),$b['slug'],$b['difficulty'],strip_tags($b['scenario']),strip_tags($b['learning_objective']),password_hash($b['flag'],PASSWORD_ARGON2ID),$b['solution'],json_encode($b['references']??[]),max(1,(int)$b['base_points'])]);$id=(int)$db->lastInsertId();$h=$db->prepare('INSERT INTO ctf_hints(challenge_id,hint_order,content,penalty_percent) VALUES(?,?,?,?)');foreach(array_values($b['hints']??[]) as $i=>$value)$h->execute([$id,$i+1,strip_tags((string)$value),[10,15,25][$i]]);$db->prepare("INSERT INTO ctf_activity_logs(actor_user_id,action,entity_type,entity_id,metadata_json,ip_hash) VALUES(?,'challenge_created','challenge',?,'{}',?)")->execute([$user['id'],$id,hash_hmac('sha256',$_SERVER['REMOTE_ADDR']??'unknown',$c['pepper'])]);$db->commit();Api::json(['id'=>$id],201);}Api::error('Admin endpoint tidak ditemukan',404);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log($e->getMessage());Api::error('Terjadi kesalahan server',500);}
